// === Tab: mySketch ===
let r = 255;
let g = 0;
let b = 0;
let yu = screen.height/2;
let yd = screen.height/2;
let xd = screen.width/2;
let xl = screen.width/2;
let rn = -1;
let rp = 1;
function setup() {
   createCanvas(screen.width, screen.height);
   noStroke();
   background(0);
}
function mp(){
   let rc = 5;
   if(r>=255 && b<=0){g+=rc;}
   if(g>=255 && !(r<=0)){r-=rc;}
   if(r<=0 && !(b>=255)){b+=rc;}
   if(b>=255 && !(g<=0) && r<=0){g-=rc;}
   if(b>=255 && !(r>=255) && g<=0){r+=rc;}
   if(r>=255 && g<=0 && !(b<=0)){b-=rc;}
}
function bounce(){
   if(xd>=width||xl>=width){rp*=-1;rn*=-1;}
}
function rgb(){
   fill(0);
   rect(0,20,150,40);
   textSize(30);
   fill(255);
   text(r+","+g+","+b+" ",0,50);
}
function draw() {
   mp();
   fill(r,g,b);
   rect(xd,0,1,height);
   xd+=rp;
   rect(xl,0,1,height);
   xl+=rn;
   rect(0,yu,width,1);
   yu+=rn;
   rect(0,yd,width,1);
   yd+=rp;
   bounce();
   rgb();
}

